<link rel="stylesheet" href="/assets/admin-crud.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/admin-crud.css'))?>"><div class="crud-heading"><div><p>LAYANAN</p><h1>Kelola layanan</h1></div></div><?php if(isset($_GET['saved'])):?><p class="ok crud-message">Layanan berhasil disimpan.</p><?php elseif(isset($_GET['deleted'])):?><p class="ok crud-message">Layanan berhasil dihapus.</p><?php elseif(isset($_GET['error'])):?><p class="alert crud-message"><?=e(match($_GET['error']){'has_history'=>'Layanan tidak dapat dihapus karena sudah memiliki riwayat antrean. Nonaktifkan layanan untuk mempertahankan laporan.','assigned_user'=>'Layanan masih ditugaskan kepada pengguna operator. Ubah penugasan pengguna terlebih dahulu.','not_found'=>'Layanan tidak ditemukan.',default=>'Layanan tidak dapat dihapus.'})?></p><?php endif?><div class="grid2 crud-grid"><section class="card"><h2 id="service-form-title">Tambah layanan</h2><form method="post" id="service-form"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="service-id"><label>Nama layanan<input name="name" id="service-name" required></label><label>Kode<input name="code" id="service-code" maxlength="10" required></label><label>Deskripsi<input name="description" id="service-description"></label><label>Warna<input type="color" name="color" id="service-color" value="#2563eb"></label><label>Estimasi menit<input type="number" name="minutes" id="service-minutes" min="1" value="5"></label><label class="media-check"><input type="checkbox" name="active" id="service-active" checked> Aktif</label><button type="submit">Simpan layanan</button><button type="button" class="secondary" id="service-reset">Layanan baru</button></form></section><section class="crud-table-card"><div class="crud-table-wrap"><table><thead><tr><th>Kode</th><th>Layanan</th><th>Estimasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><span class="code" style="background:<?=e($s['color'])?>"><?=e($s['code'])?></span></td><td><b><?=e($s['name'])?></b><?php if($s['description']):?><small class="crud-description"><?=e($s['description'])?></small><?php endif?></td><td><?=e($s['avg_service_minutes'])?> menit</td><td><span class="crud-status <?=$s['active']?'is-active':'is-inactive'?>"><?=$s['active']?'Aktif':'Nonaktif'?></span></td><td><div class="crud-actions"><button type="button" class="edit-service secondary" data-service='<?=e(json_encode(['id'=>$s['id'],'name'=>$s['name'],'code'=>$s['code'],'description'=>$s['description'],'color'=>$s['color'],'minutes'=>(int)$s['avg_service_minutes'],'active'=>(bool)$s['active']],JSON_UNESCAPED_UNICODE))?>'>Edit</button><form method="post" class="delete-form" data-name="<?=e($s['name'])?>"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($s['id'])?>"><button type="submit" class="danger">Hapus</button></form></div></td></tr><?php endforeach?></tbody></table></div></section></div><script src="/assets/services.js?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/services.js'))?>"></script><script src="/assets/admin-crud.js?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/admin-crud.js'))?>"></script>
